/**
 * mpu6050.c
 * MPU6050 driver with structured error handling, timeouts, retries,
 * bus recovery and fault injection.
 */
#include "mpu6050.h"
#include "i2c.h" /* hi2c1 and MX_I2C1_Init() generated by CubeMX */

#define MPU_ADDR          (0x68u << 1) /* HAL expects the 8-bit (shifted) address */
#define REG_PWR_MGMT_1    0x6Bu
#define REG_ACCEL_XOUT_H  0x3Bu
#define REG_TEMP_OUT_H    0x41u
#define REG_WHO_AM_I      0x75u
#define WHO_AM_I_EXPECTED 0x68u

#define I2C_TIMEOUT_MS    10u /* max time for one I2C transaction */
#define I2C_MAX_RETRIES   3u

static bool         s_ready     = false;
static uint32_t     s_err_count = 0u;
static fault_mode_t s_fault     = FAULT_NONE;

/* Convert a HAL return code (+ HAL error flags) into our own error code */
static sensor_status_t map_hal_status(HAL_StatusTypeDef hal_status)
{
    uint32_t err;

    switch (hal_status)
    {
    case HAL_OK:
        return SENSOR_OK;
    case HAL_TIMEOUT:
        return SENSOR_ERR_TIMEOUT;
    case HAL_BUSY:
        return SENSOR_ERR_BUSY;
    default:
        err = HAL_I2C_GetError(&hi2c1);
        if (err & HAL_I2C_ERROR_AF)      { return SENSOR_ERR_NACK; }
        if (err & HAL_I2C_ERROR_TIMEOUT) { return SENSOR_ERR_TIMEOUT; }
        return SENSOR_ERR_BUS;
    }
}

/* Returns the injected error if fault injection is active, otherwise SENSOR_OK */
static sensor_status_t injected_fault(void)
{
    if (s_fault == FAULT_NACK)    { s_err_count++; return SENSOR_ERR_NACK; }
    if (s_fault == FAULT_TIMEOUT) { s_err_count++; return SENSOR_ERR_TIMEOUT; }
    return SENSOR_OK;
}

static bool needs_bus_recovery(sensor_status_t st)
{
    /* A NACK means "nobody answered" - the bus itself is fine.
     * Timeouts / busy / bus errors can leave the peripheral stuck. */
    return (st == SENSOR_ERR_TIMEOUT) || (st == SENSOR_ERR_BUSY) || (st == SENSOR_ERR_BUS);
}

static sensor_status_t i2c_read(uint8_t reg, uint8_t *buf, uint16_t len)
{
    sensor_status_t st = injected_fault();
    if (st != SENSOR_OK) { return st; }

    for (uint32_t attempt = 0u; attempt < I2C_MAX_RETRIES; attempt++)
    {
        st = map_hal_status(HAL_I2C_Mem_Read(&hi2c1, MPU_ADDR, reg, I2C_MEMADD_SIZE_8BIT,
                                             buf, len, I2C_TIMEOUT_MS));
        if (st == SENSOR_OK) { return SENSOR_OK; }

        s_err_count++;
        if (needs_bus_recovery(st)) { mpu6050_recover_bus(); }
    }
    return st;
}

static sensor_status_t i2c_write(uint8_t reg, uint8_t *buf, uint16_t len)
{
    sensor_status_t st = injected_fault();
    if (st != SENSOR_OK) { return st; }

    for (uint32_t attempt = 0u; attempt < I2C_MAX_RETRIES; attempt++)
    {
        st = map_hal_status(HAL_I2C_Mem_Write(&hi2c1, MPU_ADDR, reg, I2C_MEMADD_SIZE_8BIT,
                                              buf, len, I2C_TIMEOUT_MS));
        if (st == SENSOR_OK) { return SENSOR_OK; }

        s_err_count++;
        if (needs_bus_recovery(st)) { mpu6050_recover_bus(); }
    }
    return st;
}

void mpu6050_recover_bus(void)
{
    /* Reset the I2C peripheral back to a clean state */
    HAL_I2C_DeInit(&hi2c1);
    MX_I2C1_Init();
}

sensor_status_t mpu6050_init(void)
{
    uint8_t id = 0u;
    uint8_t wake = 0x00u; /* clear SLEEP bit, use internal oscillator */
    sensor_status_t st;

    s_ready = false;

    st = i2c_read(REG_WHO_AM_I, &id, 1u);
    if (st != SENSOR_OK) { return st; }
    if (id != WHO_AM_I_EXPECTED) { return SENSOR_ERR_ID; }

    st = i2c_write(REG_PWR_MGMT_1, &wake, 1u);
    if (st != SENSOR_OK) { return st; }

    s_ready = true;
    return SENSOR_OK;
}

/* If the sensor was not ready (e.g. unplugged at boot), try to bring it up again.
 * This gives automatic recovery once the fault disappears. */
static sensor_status_t ensure_ready(void)
{
    if (s_ready && (s_fault == FAULT_NONE)) { return SENSOR_OK; }
    if (s_fault != FAULT_NONE) { return injected_fault(); }
    return mpu6050_init();
}

sensor_status_t mpu6050_read_temp_centi(int32_t *temp_c_x100)
{
    uint8_t raw[2];
    int16_t value;
    sensor_status_t st = ensure_ready();
    if (st != SENSOR_OK) { return st; }

    st = i2c_read(REG_TEMP_OUT_H, raw, 2u);
    if (st != SENSOR_OK) { s_ready = false; return st; }

    value = (int16_t)(((uint16_t)raw[0] << 8) | raw[1]);
    /* Datasheet: Temp(degC) = raw / 340 + 36.53  -> integer centi-degrees,
     * so we never need floating point printf on the MCU */
    *temp_c_x100 = ((int32_t)value * 100) / 340 + 3653;
    return SENSOR_OK;
}

sensor_status_t mpu6050_read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    sensor_status_t st = ensure_ready();
    if (st != SENSOR_OK) { return st; }

    st = i2c_read(REG_ACCEL_XOUT_H, raw, 6u);
    if (st != SENSOR_OK) { s_ready = false; return st; }

    *x = (int16_t)(((uint16_t)raw[0] << 8) | raw[1]);
    *y = (int16_t)(((uint16_t)raw[2] << 8) | raw[3]);
    *z = (int16_t)(((uint16_t)raw[4] << 8) | raw[5]);
    return SENSOR_OK;
}

bool mpu6050_is_ready(void)               { return s_ready; }
uint32_t mpu6050_error_count(void)        { return s_err_count; }
void mpu6050_set_fault(fault_mode_t mode) { s_fault = mode; }
fault_mode_t mpu6050_get_fault(void)      { return s_fault; }

const char *sensor_status_str(sensor_status_t status)
{
    switch (status)
    {
    case SENSOR_OK:          return "OK";
    case SENSOR_ERR_NACK:    return "I2C_NACK";
    case SENSOR_ERR_TIMEOUT: return "I2C_TIMEOUT";
    case SENSOR_ERR_BUSY:    return "I2C_BUSY";
    case SENSOR_ERR_BUS:     return "I2C_BUS";
    case SENSOR_ERR_ID:      return "SENSOR_ID";
    default:                 return "UNKNOWN";
    }
}
